//! Runtime called by `t!` expansions. Everything here is `#[doc(hidden)]`:
//! the shapes are generated by `catalog!` and may change between versions.

use super::Locale;
use super::negotiate::closest;
use crate::html::{Markup, escape_str};
use std::borrow::{Borrow, Cow};
use std::fmt::{self, Write as _};

/// How a catalog locale chooses between its `one` and `other` forms.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum __Plural {
    /// `one` for exactly 1 (en, es, de, it, nl, pt-PT).
    One,
    /// `one` for 0 and 1 (pt, pt-BR, fr).
    ZeroOne,
    /// Always `other` (ja, zh, ko).
    Other,
}

impl __Plural {
    fn is_one(self, count: u64) -> bool {
        match self {
            Self::One => count == 1,
            Self::ZeroOne => count <= 1,
            Self::Other => false,
        }
    }
}

/// The locales of the catalog a `t!` call was checked against.
#[doc(hidden)]
#[derive(Debug)]
pub struct __Catalog {
    pub tags: &'static [&'static str],
    pub plurals: &'static [__Plural],
    pub default: usize,
}

/// A piece of a parsed message.
#[doc(hidden)]
#[derive(Clone, Copy, Debug)]
pub enum __Segment {
    Text(&'static str),
    /// Index into the call's arguments, sorted by placeholder name.
    Arg(usize),
}

/// One locale's forms of a message; single messages only use `other`.
#[doc(hidden)]
#[derive(Debug)]
pub struct __Forms {
    pub one: &'static [__Segment],
    pub other: &'static [__Segment],
}

/// Accepts a `Locale` or a reference to one.
#[doc(hidden)]
pub fn __locale<L: Borrow<Locale>>(locale: &L) -> Locale {
    *locale.borrow()
}

impl __Catalog {
    /// The segments for `locale`: its own tag, else a locale with its
    /// language, else the catalog default, so a locale negotiated from
    /// another crate's list still finds a message.
    fn select(
        &self,
        locale: Locale,
        count: Option<u64>,
        forms: &[__Forms],
    ) -> &'static [__Segment] {
        let mut index = closest(self.tags, self.default, locale.tag()).unwrap_or(self.default);
        if index >= forms.len() {
            index = self.default;
        }
        let Some(form) = forms.get(index) else {
            return &[];
        };
        let one = count.is_some_and(|n| self.plurals.get(index).is_some_and(|rule| rule.is_one(n)));
        if one { form.one } else { form.other }
    }
}

/// Renders a plain-text message; static messages are borrowed.
#[doc(hidden)]
pub fn __text(
    catalog: &__Catalog,
    locale: Locale,
    count: Option<u64>,
    forms: &[__Forms],
    args: &[&dyn fmt::Display],
) -> Cow<'static, str> {
    match catalog.select(locale, count, forms) {
        [] => Cow::Borrowed(""),
        [__Segment::Text(text)] => Cow::Borrowed(*text),
        segments => {
            let mut out = String::new();
            for segment in segments {
                match segment {
                    __Segment::Text(text) => out.push_str(text),
                    __Segment::Arg(index) => {
                        if let Some(arg) = args.get(*index) {
                            let _ = write!(out, "{arg}");
                        }
                    }
                }
            }
            Cow::Owned(out)
        }
    }
}

/// Renders a `*_html` message: the template is trusted, arguments are
/// HTML-escaped.
#[doc(hidden)]
pub fn __html(
    catalog: &__Catalog,
    locale: Locale,
    count: Option<u64>,
    forms: &[__Forms],
    args: &[&dyn fmt::Display],
) -> Markup {
    let mut out = String::new();
    for segment in catalog.select(locale, count, forms) {
        match segment {
            __Segment::Text(text) => out.push_str(text),
            __Segment::Arg(index) => {
                if let Some(arg) = args.get(*index) {
                    out.push_str(&escape_str(&arg.to_string()));
                }
            }
        }
    }
    Markup::from_trusted(out)
}

